// Pages come from the agent as a comma/space-separated list of refs from search_pages: file_id:page[:tile]
const q = $json.question || '';
const refs = String($json.pages || '').split(/[\s,;]+/).map(s => s.trim()).filter(s => /^[A-Za-z0-9!_-]+:\d+(:\d+)?$/.test(s)).slice(0, 4);
return [{ json: { question: q, refs } }];

const RULES = [
  'You read pages from an engineering knowledge base: plan sheets, construction details, scanned manuals, charts and photos.',
  'Answer the question only from what the images show. Quote labels, dimensions, notes and table values exactly as printed.',
  'Reading a value off a chart or curve: (1) read both axis labels, units and the value of each grid line; (2) find the grid line for the given x value;',
  '(3) find the named curve. In a FAMILY of curves (e.g. 1, 2, 5, 10, 25, 50, 100-year), curves never cross, so identify them by ORDER: where the labels are printed,',
  '    list every curve from the bottom up with its label (e.g. "1st = 1-yr, 2nd = 2-yr, 3rd = 5-yr ..."); then at the target x count curves from the bottom up to reach the',
  '    same ordinal. State that count in your answer (e.g. "the 4th curve from the bottom = 10-year").',
  '    CROSS-CHECK: count the curves at the target x too. If there are more curves than labels in your list, you missed a label (small labels on the',
  '    lowest or most crowded curves are easy to miss, e.g. a "1" that looks like "/"); find it and redo the order before reading.',
  '(4) count grid cells from the nearest labelled y value to where the curve crosses;',
  '(5) give your best estimate, then a range of plus/minus ONE minor grid division around it (e.g. best 5.4, grid 0.2 -> "about 5.4 in/hr (5.2–5.6)"), naming the curve and axes;',
  '(6) always end a chart reading with: "Read from the chart — verify on the figure (or a published table/equation) before using it for design."',
  'When you get a whole sheet plus zoomed tiles of it, use the tiles for small text, dimensions and notes, and the whole sheet for layout and labels.',
  'On plans and profiles, identify each structure or material by matching its hatch/fill pattern to the sheet legend, and name its type (e.g. cascade, cobble riffle, riprap) — a station or elevation alone is not a structure.',
  'If the images do not show the answer, say so plainly. Do not guess and do not use outside knowledge as if it were on the page.',
  'Cite each fact as (file name, page N). Be concise: a few sentences or a short list.'
].join('\n');
const describe = imgs => imgs.map((m, i) => `${i + 1}) ${m.file_name}, page ${m.page_no}` +
  (m.kind === 'tile' ? ` — zoomed tile, row ${Math.floor(m.tile_ix / 4) + 1} of 3, column ${m.tile_ix % 4 + 1} of 4 (tiles overlap slightly)` : '')).join('; ');
// Pass 1: look at the pages. Answer, or ask for a zoom when a precise reading needs a closer look (charts, tiny text).
const imgs = $input.first().json.images || [];
const q = $('Parse page refs').first().json.question;
if ($input.first().json.error) return [{ json: { skip: true, response: 'VISUAL SEARCH UNAVAILABLE: the local vision service did not respond. '
  + 'Tell the user you could not look at the pages right now. Do NOT say the sheet or figure does not exist.' } }];
if (!imgs.length) return [{ json: { skip: true, response: 'No page images found for those refs. Use refs exactly as search_pages returned them.' } }];
const ZOOM = 'Reply as JSON: {"answer": "...", "zoom": null} or {"answer": "your draft", "zoom": {"image": N, "box": [x0, y0, x1, y1]}}. '
  + 'Ask for a zoom (image number, box as fractions 0-1 of that image) whenever you must READ A VALUE OFF A CHART OR CURVE, '
  + 'or key text/dimensions are too small to read with confidence. For a chart, the box must span the target x from just below the LOWEST curve '
  + 'to just above the HIGHEST curve (so every curve can be counted from the bottom up) and include the nearest labelled grid values on both axes. '
  + 'In your draft answer, record the bottom-up order of the curves and which ordinal the named curve is. Otherwise give the final answer with "zoom": null.';
const content = [{ type: 'text', text: `Question: ${q}\n\nImages: ${describe(imgs)}.` }];
for (const m of imgs) content.push({ type: 'image_url', image_url: { url: `data:image/png;base64,${m.png_b64}`, detail: 'high' } });
return [{ json: { skip: false, body: { model: 'gpt-5.4-mini', reasoning_effort: 'medium', max_completion_tokens: 6000,
  response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: RULES + '\n' + ZOOM }, { role: 'user', content }] } } }];

// Did pass 1 ask for a zoom? If so, prepare the crop request; otherwise its answer is final.
// A failed read is not a reading (design part 2; rulings R70, R73): the agent is told what happened and an incident is
// logged ("Log incident" -> RAG – Error reporter). truncated_pass1 = cut off by the token budget (finish_reason "length");
// empty_reply = no text for another reason (stop, content_filter); vision_error = no reply (the Azure call failed).
// Every failure text ends with "Tell the user; do not guess." (R80). The reason never quotes the question or the reply.
const m = $input.first().json;
const choice = m.choices?.[0];
const raw = choice?.message?.content;
const why = (r) => {
  const c = r.choices?.[0] ?? {}, u = r.usage ?? {}, rt = u.completion_tokens_details?.reasoning_tokens;
  const fr = String(c.finish_reason ?? 'none').replace(/content_filter/i, 'filter').slice(0, 20);   // the scrub cuts at "content"
  return `finish_reason ${fr}, ${c.message?.content ? 'partial' : 'empty'} reply`
    + (u.completion_tokens != null ? `, ${Number(u.completion_tokens)} completion tokens` : '')
    + (rt != null ? ` (${Number(rt)} reasoning)` : '');
};
const errText = (e) => String((e !== null && typeof e === 'object' ? e.message : e) || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 120);
const failed = (r) => r.error ? `Azure call failed: ${errText(r.error)}` : 'no reply from the model';
const failedRead = (response, incident, reason) => [{ json: { zoom: false, response, incident,
  incident_node: 'gpt-5.4-mini looks at the pages', incident_message: 'first look: ' + reason } }];
if (choice?.finish_reason === 'length') return failedRead("The vision model's reading was cut off; ask a narrower question. Tell the user; do not guess.", 'truncated_pass1', why(m));
if (choice && !raw) return failedRead("The vision model returned no reading for these pages; try again or ask about a specific detail. Tell the user; do not guess.", 'empty_reply', why(m));
if (!raw) return failedRead('The vision model could not read the pages right now' + (m.error ? ' (' + String(m.error.message || m.error).slice(0, 120) + ')' : '') + '. Tell the user; do not guess.',
  'vision_error', failed(m));
let j; try { j = JSON.parse(raw); } catch (e) { return [{ json: { zoom: false, response: raw } }]; }
const imgs = $('Vision service: page images').first().json.images || [];
const z = j.zoom, idx = z && Number(z.image) - 1, img = imgs[idx];
if (!z || !img || !Array.isArray(z.box) || z.box.length !== 4) return [{ json: { zoom: false, response: String(j.answer || raw) } }];
const [fid, pno] = String(img.ref).split(':');
return [{ json: { zoom: true, draft: String(j.answer || ''), image: idx + 1,
  crop: { file_id: fid, page_no: Number(pno), kind: img.kind, tile_ix: img.tile_ix ?? null, box: z.box.map(Number), max_side: 1800 } } }];

const RULES = [
  'You read pages from an engineering knowledge base: plan sheets, construction details, scanned manuals, charts and photos.',
  'Answer the question only from what the images show. Quote labels, dimensions, notes and table values exactly as printed.',
  'Reading a value off a chart or curve: (1) read both axis labels, units and the value of each grid line; (2) find the grid line for the given x value;',
  '(3) find the named curve. In a FAMILY of curves (e.g. 1, 2, 5, 10, 25, 50, 100-year), curves never cross, so identify them by ORDER: where the labels are printed,',
  '    list every curve from the bottom up with its label (e.g. "1st = 1-yr, 2nd = 2-yr, 3rd = 5-yr ..."); then at the target x count curves from the bottom up to reach the',
  '    same ordinal. State that count in your answer (e.g. "the 4th curve from the bottom = 10-year").',
  '    CROSS-CHECK: count the curves at the target x too. If there are more curves than labels in your list, you missed a label (small labels on the',
  '    lowest or most crowded curves are easy to miss, e.g. a "1" that looks like "/"); find it and redo the order before reading.',
  '(4) count grid cells from the nearest labelled y value to where the curve crosses;',
  '(5) give your best estimate, then a range of plus/minus ONE minor grid division around it (e.g. best 5.4, grid 0.2 -> "about 5.4 in/hr (5.2–5.6)"), naming the curve and axes;',
  '(6) always end a chart reading with: "Read from the chart — verify on the figure (or a published table/equation) before using it for design."',
  'When you get a whole sheet plus zoomed tiles of it, use the tiles for small text, dimensions and notes, and the whole sheet for layout and labels.',
  'On plans and profiles, identify each structure or material by matching its hatch/fill pattern to the sheet legend, and name its type (e.g. cascade, cobble riffle, riprap) — a station or elevation alone is not a structure.',
  'If the images do not show the answer, say so plainly. Do not guess and do not use outside knowledge as if it were on the page.',
  'Cite each fact as (file name, page N). Be concise: a few sentences or a short list.'
].join('\n');
const describe = imgs => imgs.map((m, i) => `${i + 1}) ${m.file_name}, page ${m.page_no}` +
  (m.kind === 'tile' ? ` — zoomed tile, row ${Math.floor(m.tile_ix / 4) + 1} of 3, column ${m.tile_ix % 4 + 1} of 4 (tiles overlap slightly)` : '')).join('; ');
// Pass 2: the same images + the enlarged region. The close-up gives the precise reading; the full image gives labels and axes.
const imgs = $('Vision service: page images').first().json.images || [];
const q = $('Parse page refs').first().json.question;
const d = $('Zoom requested?').first().json;
const crop = $input.first().json;
if (!crop.png_b64) return [{ json: { body: null } }];   // crop failed: "Crop ok?" skips the model, "Return the reading" reports it
const content = [{ type: 'text', text: `Question: ${q}\n\nImages: ${describe(imgs)}; ${imgs.length + 1}) ENLARGED VIEW of image ${d.image}, `
  + `region x ${crop.box?.[0]}–${crop.box?.[2]}, y ${crop.box?.[1]}–${crop.box?.[3]} (fractions of that image), zoom x${crop.zoom}.\n`
  + `Your first look said: "${d.draft}". In the enlarged view, at the target x count the curves from the bottom up to the ordinal of the named `
  + `curve (from image ${d.image} and your first look), then read its value by counting grid cells from a labelled value. Give the final answer in plain text, `
  + `stating which curve (ordinal from the bottom) you read.` }];
for (const m of imgs) content.push({ type: 'image_url', image_url: { url: `data:image/png;base64,${m.png_b64}`, detail: 'high' } });
if (crop.png_b64) content.push({ type: 'image_url', image_url: { url: `data:image/png;base64,${crop.png_b64}`, detail: 'high' } });
return [{ json: { body: { model: 'gpt-5.4-mini', reasoning_effort: 'medium', max_completion_tokens: 6000,
  messages: [{ role: 'system', content: RULES }, { role: 'user', content }] } } }];

// Pass 2 result (design part 2; rulings R70, R73). Every failed zoom pass returns the first-look draft marked as
// approximate and logs an incident: truncated_pass2 = the reply was cut off (finish_reason "length") or had no text;
// zoom_failed = no reply at all: the crop failed (then "Crop ok?" skipped the model) or the close-up call failed.
const m = $input.first().json;
const fallback = $('Zoom requested?').first().json.draft;
const choice = m.choices?.[0];
const why = (r) => {
  const c = r.choices?.[0] ?? {}, u = r.usage ?? {}, rt = u.completion_tokens_details?.reasoning_tokens;
  const fr = String(c.finish_reason ?? 'none').replace(/content_filter/i, 'filter').slice(0, 20);   // the scrub cuts at "content"
  return `finish_reason ${fr}, ${c.message?.content ? 'partial' : 'empty'} reply`
    + (u.completion_tokens != null ? `, ${Number(u.completion_tokens)} completion tokens` : '')
    + (rt != null ? ` (${Number(rt)} reasoning)` : '');
};
const errText = (e) => String((e !== null && typeof e === 'object' ? e.message : e) || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 120);
const failed = (r) => r.error ? `Azure call failed: ${errText(r.error)}` : 'no reply from the model';
const failedRead = (incident, node, reason, alt) => [{ json: {
  response: fallback ? '(zoom failed; first-look reading, approximate) ' + fallback : alt,
  incident, incident_node: node, incident_message: 'zoom pass: ' + reason } }];
const COULD_NOT = 'The vision model could not read the pages right now. Tell the user; do not guess.';
if ($('Build zoomed request').first().json.body === null) {
  const c = $('Vision service: crop').first().json;
  return failedRead('zoom_failed', 'Vision service: crop', 'crop failed: ' + (c.error ? errText(c.error) : 'no image returned'), COULD_NOT);
}
if (!choice) return failedRead('zoom_failed', 'gpt-5.4-mini reads the close-up', failed(m), COULD_NOT);
if (choice.finish_reason === 'length' || !choice.message?.content)
  return failedRead('truncated_pass2', 'gpt-5.4-mini reads the close-up', why(m), "The vision model's reading was cut off; ask a narrower question. Tell the user; do not guess.");
return [{ json: { response: choice.message.content } }];

// What the agent gets: the response of the step that decided it ("Return the reading" after a zoom, else "Zoom requested?"),
// read by name, so "Log incident" (the reporter's reply, or its error item) never changes it.
const d = ($('Return the reading').isExecuted ? $('Return the reading') : $('Zoom requested?')).first().json;
return [{ json: { response: d.response } }];
